import { useEffect, useRef } from 'react';

import { useToast } from 'contexts';
import { FilterForm } from 'models/Filters';

export interface FilterAlertDescriptor {
  key: string;
  type?: 'info' | 'warning' | 'success' | 'error';
  isOpen: boolean;
  title: string;
  message: string | React.ReactNode;
  closeButtonLabel?: string;
  actionMessage?: string;
  onAction?: () => void;
  onClose: () => void;
  suppressInitial?: boolean;
}

interface FilterAlertManagerProps {
  pageName: string;
  currentPage: string | null;
  applied: FilterForm;
  isLoaded: boolean;
  isLoading?: boolean;
  alerts: FilterAlertDescriptor[];
  width?: string;
}

const getToastId = (pageName: string, key: string) =>
  `${pageName}:filter-alert:${key}`;

export const FilterAlertManager: React.FC<FilterAlertManagerProps> = ({
  pageName,
  currentPage,
  applied,
  isLoaded,
  isLoading = false,
  alerts,
  width = '509px',
}) => {
  const toast = useToast();
  const initialSignatureRef = useRef<string | null>(null);
  const hasCompletedInitialLoadRef = useRef(false);
  const alertKeysRef = useRef<string[]>([]);
  alertKeysRef.current = alerts.map((alert) => alert.key);

  useEffect(
    () => () => {
      alertKeysRef.current.forEach((key) =>
        toast.dismiss(getToastId(pageName, key)),
      );
    },
    [pageName, toast],
  );

  useEffect(() => {
    const dismissAlert = (alert: FilterAlertDescriptor) =>
      toast.dismiss(getToastId(pageName, alert.key));

    const showAlert = (alert: FilterAlertDescriptor) => {
      const toastId = getToastId(pageName, alert.key);
      const showToast = toast[alert.type ?? 'warning'];

      showToast({
        id: toastId,
        width,
        title: alert.title,
        message: alert.message,
        closeButtonLabel: alert.closeButtonLabel,
        firstAction:
          alert.actionMessage && alert.onAction
            ? {
                actionMessage: alert.actionMessage,
                onActionClick: alert.onAction,
              }
            : undefined,
        onClose: alert.onClose,
      });
    };

    if (currentPage !== pageName) {
      initialSignatureRef.current = null;
      hasCompletedInitialLoadRef.current = false;
      alerts.forEach(dismissAlert);
      return;
    }

    if (!isLoaded) {
      initialSignatureRef.current = null;
      hasCompletedInitialLoadRef.current = false;
      alerts.forEach(dismissAlert);
      return;
    }

    if (isLoading) {
      alerts.forEach(dismissAlert);
      return;
    }

    const currentSignature = JSON.stringify(applied);
    if (
      !hasCompletedInitialLoadRef.current ||
      initialSignatureRef.current === null
    ) {
      hasCompletedInitialLoadRef.current = true;
      initialSignatureRef.current = currentSignature;
      alerts.forEach((alert) => {
        if (alert.isOpen && alert.suppressInitial === false) {
          showAlert(alert);
        } else {
          dismissAlert(alert);
        }
      });
      return;
    }

    alerts.forEach((alert) => {
      if (!alert.isOpen) {
        dismissAlert(alert);
        return;
      }

      showAlert(alert);
    });
  }, [
    alerts,
    applied,
    currentPage,
    isLoaded,
    isLoading,
    pageName,
    toast,
    width,
  ]);

  return null;
};
